from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
SAFE=['Tiyakin ang qualification,training,duty scope,at aprubadong procedure sa equipment operation,measurement,machining,o setting change.']
m.lesson(90,'Pagtiyak ng cutting order at hugis na iiwan','Ihiwalay ang drilling/threading sequence,tools,at feed conditions.',[
('Hole at thread:ibang yugto','Sa hand-made large square hole example,magkakahiwalay na small holes sa loob ng outline,putulin ang pagitan,at i-file ang finishing allowance. Huwag lampasan ang scribe;kontrolin ang fixation/sharp edges. Huwag general hole/chamfer values ang utos;ayon sa drawing/material.'),('Tap at edge types','Sa hand tap set,may taper,second,bottoming sequence. Piliin ayon sa blind/through hole at type;huwag parehong reverse amount sa lahat. Drill flute tumutulong sa chips.118°tip ang representative,hindi lahat ng material. Ihiwalay ang brazed at indexable lathe tools.'),('Machine parts at feed','Lathe:headstock,chuck,toolpost,tailstock,feed;pinagsasama ang workpiece rotation/tool feed. Milling:relative motion ng spindle tool/table. Backlash ay play sa feed at position error sa reversal. Tingnan ang removal/compensation at specs;hindi parehong scale laging parehong actual position.')],['Materyal na iniiwan upang alisin sa finishing.'],ACT+'Ipakita ang loob/labas ng scribe at allowance sa square hole. Sa reversal na hindi agad sumusunod ang position,ihiwalay ang observation at checks.',SAFE,'Sa cutting order/retained shape,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(91,'Measurement principle at scale resolution','Ihiwalay ang resolution at accuracy at ipaliwanag ang temperature,flux,capacitance measurement.',[
('Mechanism at least reading','Textbook micrometer:0.5mm/revolution at50divisions,kaya0.01mm. Hindi pareho ang least display digit at accuracy. May dial gauge na0.001mmngunit hindi lahat;tingnan ang range,contact,management.'),('Temperature/flux conversion','Thermocouple gumagamit ng thermoelectric voltage sa temperature difference ng dalawang metal junctions. K-type range sa textbook ay example;wire diameter,protective tube,atmosphere,meter ang nagbabago sa range. Hall element:voltage perpendicular sa current at perpendicular field;ginagamit sa gaussmeter flux-density measurement.'),('Mula electrical tungong ibang quantity','Auto-balancing bridge ng LCR at iba pa gumagamit ng voltage,current,phase para sa element values. Capacitance ang charge-storage ability sa conductors;ginagamit sa thickness,displacement,liquid-level detection. Ihiwalay ang target at converted electrical quantity;hindi iisang cause ang capacitance change.')],['Voltage na kaugnay ng junction temperature difference.'],ACT+'Kalkulahin ang0.5mm/50division at ipaliwanag ang least reading/accuracy. I-arrow ang input/output ng thermocouple,Hall,capacitive displacement.',SAFE,'Sa measurement principle/resolution,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(92,'Passive-component structure at selection conditions','Ihiwalay ang passive structure/gamit at lubricant scales.',[
('Capacitor materials','May dielectric sa pagitan ng conductors. Sa aluminum electrolytic example,anode aluminum foil,dielectric aluminum oxide,kasama rin ang electrolyte. Iba ang ceramic,film,multilayer chip,variable;kahit parehong capacitance,tingnan ang polarity,temperature,frequency,aging.'),('Coil at functional elements','May wound,laminated,thin-film coils;hindi lahat nakikitang wire sa iron core. Ihiwalay ang thermistor resistance/temperature,piezo force-electricity,crystal vibration. May rectification,detection,Zener-breakdown voltage control,photoelectric conversion din sa diodes.'),('Conditional grease markings','Lubrication ang oil/grease upang mabawasan ang friction/wear. Consistency ang softness scale ngunit opposite direction ang penetration value at NLGIgrade. Huwag “mas malaki,mas malambot” sa lahat ng grease numbering. Tingnan ang standard,scale name,designated product.')],['Insulating material sa pagitan ng conductors sa capacitor at iba pa.'],ACT+'Sa same-capacitance aluminum electrolytic/ceramic replacement,ilista ang checks bukod sa capacitance. Bakit hiwalay ang consistency value at grade number?',SAFE,'Sa passive structure/selection,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(93,'Paliwanag sa field/resistance circuits ayon sa formula conditions','Ipakita ang force/circuit assumptions at ipaliwanag ang graph,voltage/current division.',[
('Charge tungong force','Cang charge unit;field ang force bawat unit charge,hindi voltage/current mismo. Sa vacuum point-charge model,Coulomb force magnitude|q1q2|/(4πε0r²). Ibang medium,ibang permittivity assumption;hindi unconditional point formula sa lahat ng malapit na bagay.'),('Graph slope','KungVhorizontal,Ivertical,slopeI/V=1/R. Mas current sa parehongV,mas maliitR. Baligtad axes,iba ang slope. Panatilihin ang fixed-temperature assumptions;hindi lahat straight-line.'),('Division ratios','Sa unloaded two-resistor series,V1=V0R1/(R1+R2). Sa parallel,I1=I0R2/(R1+R2);mas maliitR1,mas malakiI1. Sundan mula commonV atI1=V/R1kung bakit opposite resistor ang numerator. Added load/meter nagbabago sa circuit;kaya maaaring hindi valid ang original ratio.')],['Paghahati ng current sa parallel branches.'],ACT+'Sa6V,100Ωseries200Ω,kunin ang bawat voltage. Saka parallel ang parehong resistors,total90mA;hanapin ang division at check ratios.',SAFE,'Sa field/resistance formula conditions,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(94,'Pagsunod sa relay,contactor,at overload detection bilang hanay','Sundan ang switching,overload detection,at return ng magnetic starter.',[
('Contactor at thermal combination','Magnetic starter/switch ang contactor+thermal relay. Contactor:load switching;thermal:overload detection;hindi thermal lamang ang main-circuit interruption. Hindi laging pareho ang short protection;tingnan ang protection coordination.'),('Return matapos detection','Thermal operation mula heating ayon sa current/duration;kaya ihiwalay ang instant at sustained overload. Bimetal bumabaluktot sa thermal-expansion difference ng dalawang metals. Tiyakin ang cause/safety at approved reset;huwag paulit-ulit upang patuloy tumakbo.'),('Hold path at power loss','Sa basic self-hold,self-contact parallel sa start ang nagpapakuryente sa coil;stop pumuputol. Ordinaryong relay nawawalan ng energization sa power loss. Iba sa PLC retention/restart circuits;huwag tiyaking laging safely stopped sa return;tingnan ang tunay na circuit/return conditions.')],['Switching device na pinagsamang contactor at overload detector.'],ACT+'Sa limang start,release,stop,power loss,return states,itable ang basic coil energization. Bakit kailangang recheck kapag nagpalit ng retention PLCsetting?',SAFE,'Sa relay/contactor/overload,pagsamahin ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(95,'Pagtutugma ng rotating machines/transformers sa structure at conditions','Itugma ang structure,starting,loss,detection conditions ng motors/transformers.',[
('Rotor at starting','Three-phase induction may cage/wound rotors. Star-delta current reduction ay comparison sa same line voltage at angkop na winding. Nagbabago rin starting torque;kaya hindi lahat ng load dahil less current. Itugma ang starting,winding terminals,rating,load,protection.'),('Command at detection','Encoder nagsasalin ng angle/linear displacement sa code. Feedback ng servo nagwawasto ng command difference sa position,speed,torque. Ihiwalay ang feed speed at winding torque;huwag position error sa speed increase lamang.'),('Loss at medium','May textbook stray-load loss example na5～30%ng copper loss,ngunit hindi fixed sa lahat. SF6,sulfur hexafluoride,sa insulation/cooling;tingnan ang environment/handling. Iba ang vacuum/gas arc extinction at oil/molded insulation classifications;huwag sabihing walang old oil breakers.')],['Umiikot na bahagi ng motor at iba pa.'],ACT+'Gumawa ng tatlong command examples:position,speed,torque;ipaliwanag detection. Bakit hindi starting current lamang ang star-delta selection,mula load torque/rating?',SAFE,'Sa motors/transformers,pagsamahin ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(96,'Paghiwalay ng structural,environmental,at electrical tests','Ihiwalay ang structure,function,environment,safety,reliability purposes.',[
('Structural check','Suriin ang size,weight,strength,assembly structure sa specified. Hindi dimension check ang guarantee ng weight/strength. Iba ang appearance,function,structure;itugma ang test target/method.'),('Durability at external conditions','Functional:required response sa input;environment:temperature,humidity,vibration,shock. Accelerated life gumagamit ng takdang severe conditions,hindi permiso na sariling taasan ang heat/voltage. May evaluation assumptions sa accelerated/normal life relation.'),('Electrical safety at record','Iba ang insulation resistance,withstand voltage,leakage,EMS methods. General tester/oscilloscope name ay hindi lahat-test compatibility. Itugma ang equipment,applied conditions,time,criteria,operator;identify failures at link records. Hindi unconditional substitute ang supplier/component at finished-product tests.')],['Inspection na tumutugma sa structure,weight,strength at requirements.'],ACT+'Gumawa ng pitong appearance,dimension,structure,function,environment,safety,reliability columns;isang target/standard bawat isa. Bakit hindi ililipat ang isang pass sa ibang column?',SAFE,'Sa structural/environment/electrical tests,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(97,'Pagkumpara ng packaging materials at resin production conditions','Ihambing ang protective packaging sa resin method at production cost.',[
('Material/logistics requirements','Paper,cardboard,wood,metal,glass,resin containers ayon sa product/transport/storage. Square o near-square timber ang kakuzai example;packaging design ang fixation strength. Protection/efficiency kaysa decoration;huwag alisin ang needed cushion/fixation dahil minimal materials.'),('Mass production at mold cost','Injection para sa maraming same-shape sa maikling oras,ngunit may precision-mold initial cost;hindi laging cheapest sa small lots. Iba ang screw supply,holding,cooling,shrinkage. Huwag rotation speed lamang ang shot amount;tingnan ang metering/injection mechanism/standard.'),('Resin/method','Blow molding nagpapalaki sa hangin,iba sa injection. Thermoset crosslinks kaya hindi same remelting. Biodegradation condition-dependent,hindi puwedeng iwan kahit saan. May impregnation,lamination,pressing FRP;hindi lahat high-temperature/high-pressure press lamang.')],['Structural change na nag-uugnay sa polymer chains.'],ACT+'Sa20at20000products/year,ihiwalay ang initial mold cost at processing time bawat isa. Suriin kung reduced packaging ay tugma sa humidity,shock,fixation.',SAFE,'Sa packaging/resin conditions,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
m.lesson(98,'Board manufacturing stages at order of magnitude','Ihiwalay ang structure,process films,at machining scale.',[
('Board role at heat','Motherboard ang main connection ng CPU,memory,at iba pa. Metal-base board combines metal,insulating layer,copper conductor para sa heat. Hindi ibig sabihing directly conductive ang pattern sa metal base. Ihiwalay ang single/double/multilayer sa usage name.'),('Sequence','Sa conceptual subtractive copper-clad process,may cutting,drilling/copper plating,photo-film,exposure/development,etching. Iba ang solder resist,silkscreen,surface treatment,outline/V-cut,inspection;tingnan ang actual method order. Huwag same-stage ang circuit photo-film at final solder resist.'),('Chemical processing at scale','Wet etch ay chemical unwanted-copper removal,hindi mechanical polishing. Kontrolin ang concentration,temperature,cleaning. Textbook compares submillimeter board at nmsemiconductor,ngunit hindi fixed width ng lahat.1mm=10⁶nm;kaya tiyakin ang unit/order.')],['Film sa board na tumatakip at nagpoprotekta sa bahaging hindi lalagyan ng solder at iba pa.'],ACT+'Ihiwalay ang photo-film,solder resist,silkscreen sa layunin. I-convert ang0.1mm sa nm at ihiwalay ang textbook scale comparison sa individual design.',SAFE,'Sa board stages/magnitude,tingnan ang structure,gamit,applicability,bukod sa pangalan.')
